-- load_customer_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.Customer_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedCustomerData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/customer.json changes it for the holdout.
DECLARE @MonthsBack   int = 41;
DECLARE @WindowMonths int = 1;
--    Only one batch of data exists, so dev and holdout are split by [WWI Customer ID]:
--    even IDs are the dev batch (the default), odd IDs the holdout.
DECLARE @IdRemainder  int = 0;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Customer');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.Customer_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [WWI Customer ID] int,
    [Customer] nvarchar(100),
    [Bill To Customer] nvarchar(100),
    [Category] nvarchar(50),
    [Buying Group] nvarchar(50),
    [Primary Contact] nvarchar(50),
    [Postal Code] nvarchar(10),
    [Valid From] datetime2(7),
    [Valid To] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetCustomerUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

INSERT INTO Integration.Customer_Staging ([WWI Customer ID], [Customer], [Bill To Customer], [Category], [Buying Group], [Primary Contact], [Postal Code], [Valid From], [Valid To])
SELECT [WWI Customer ID], [Customer], [Bill To Customer], [Category], [Buying Group], [Primary Contact], [Postal Code], [Valid From], [Valid To]
FROM #rows
WHERE [WWI Customer ID] % 2 = @IdRemainder;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedCustomerData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Customer', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.Customer_Staging;
